insert into public.curricula (id, title, subject, description) values
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'Nigerian National Curriculum (NERDC) — WAEC SSCE Aligned', 'Mathematics', 'SS1-SS3 core Mathematics, sourced from the Lagos State Ministry of Education scheme of work.'),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000002', 'Nigerian National Curriculum (NERDC) — WAEC SSCE Aligned', 'Further Mathematics', 'SS1-SS3 Further Mathematics, sourced from the Lagos State Ministry of Education scheme of work.')
insert into public.topics (curriculum_id, class_level, term, title, description, order_index) values
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 1, 'Revision of JSS3 Work & Operations on Integers', 'Revision of JSS3 work and basic operations on integers — addition, subtraction, multiplication and division.', 101),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 1, 'Number Bases', 'Number Bases — (a) conversion from one base to base ten, (b) conversion of decimal fractions ("bicimals") in one base to base ten, (c) conversion of numbers from one base to another.', 102),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 1, 'Number Bases: Arithmetic & Applications', 'Number Bases (continued) — (a) addition, subtraction, multiplication and division of numbers in different bases, (b) application of number bases to computer programming.', 103),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 1, 'Modular Arithmetic', 'Concept of Modular Arithmetic — addition, subtraction, multiplication and division operations in modular arithmetic.', 104),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 1, 'Standard Form and Approximation', 'Standard Form and Approximation.', 105),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 1, 'Indices', 'Indices — (a) application of laws of indices, (b) negative, zero and fractional indices.', 106),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 1, 'Logarithms of Numbers Greater Than 1', 'Logarithms of numbers greater than 1 (whole numbers) — use of logarithm tables for multiplication and division of numbers.', 107),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 1, 'Logarithms: Powers, Roots & Relationship to Indices', 'Logarithms (continued) — (a) calculations involving powers and roots, (b) relationship between indices and logarithms.', 108),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 1, 'Simple Equations, Variation & Change of Subject', '(a) Simple equations and variation, (b) change of subject of formulae, (c) types of variation — direct, inverse, joint and partial, (d) application of variation to practical problems.', 109),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 2, 'Quadratic Equations: Factorisation & Completing the Square', 'Quadratic Equations by (a) factorisation, (b) completing the square method.', 201),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 2, 'Quadratic Formula', 'General form of a quadratic equation leading to the formula method, from ax² + bx + c = 0.', 202),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 2, 'Quadratic Equations: Graphical Method', 'Solving quadratic equations by graphical methods — reading the roots from the graph; determination of minimum and maximum values; line of symmetry.', 203),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 2, 'Idea of Sets', 'Idea of Sets — universal sets, finite and infinite sets, empty set, subsets.', 204),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 2, 'Set Notation: Union, Intersection & Complement', 'Notation for union and intersection of sets; complements of sets; disjoint/null sets.', 205),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 2, 'Venn Diagrams', 'Venn diagrams and their use in solving problems involving two and three sets, in relation to real-life situations.', 206),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 2, 'Trigonometric Ratios', 'Trigonometric Ratios — sine, cosine, tangent of acute angles; use of tables of trigonometric ratios; determination of length of chord using trigonometric ratios.', 207),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 2, 'Sine & Cosine Graphs; Trig Applications', 'Graph of sine and cosine for angles 0°–360°; (a) application of sine, cosine and tangent to simple problems on right-angled triangles, (b) angles of elevation and depression, (c) bearing and distances of places (strict application of trigonometric ratios).', 208),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 2, 'Circles: Introduction, Arc Length, Sectors & Segments', '(a) Introduction to circles and their properties, (b) calculation of length of arc and perimeter of a sector, (c) area of sectors and segments; area of triangles.', 209),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 2, 'Logic: Statements & Implication', 'Logic — simple true and false statements; negation and contrapositive of a simple statement; antecedent, consequent and conditional statements (implication).', 210),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Mensuration: 3-D Shapes, Surface Area & Volume', 'Mensuration — the concept of 3-D shapes: cube, cuboid, cylinder, triangular prism, cone, rectangular-based pyramid; total surface area of cone and cylinder and their volumes.', 301),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Frustums & Angle Sum of a Triangle', '(a) Volumes of frustums of cones, rectangular-based pyramids and other pyramids, (b) proof that the angle sum of a triangle = 180°, (c) the exterior angle of a triangle.', 302),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Geometrical Construction: Triangles & Line Segments', 'Geometrical Construction — revision of construction of triangles; drawing and bisection of a line segment; construction and bisection of angles 90°, 45°, 135°, 22½°, 57½°.', 303),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Construction & Bisection of Angles', 'Construction and bisection of angles: 30°, 60°, 90°, 120°, 150°, etc.', 304),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Construction of Quadrilaterals & Equilateral Triangles', 'Construction of a quadrilateral polygon (a four-sided figure with given conditions, e.g. a parallelogram); construction of an equilateral triangle.', 305),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Locus of Moving Points', 'Locus of moving points, including equidistance from two lines/two points, and constant distance from a point.', 306),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Deductive Proof: Angle Sum of a Triangle', 'Deductive proof: sum of angles of a triangle; relationship of triangles on a straight line.', 307),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Parallel Lines, Congruent Triangles & Parallelograms', 'Revision of angles on parallel lines cut by a transversal; congruent triangles; properties of a parallelogram and the intercept theorem.', 308),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Statistics: Data Collection & Presentation', 'Statistics — collection, tabulation and presentation of data (e.g. heights, ages, weights, test/exam scores, school/class populations, animal species, vehicle types, etc.).', 309),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Range, Median & Mode (Ungrouped Data)', 'Calculation of range, median and mode of ungrouped data (using data collected by students or from other statistical records).', 310),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Grouped Data: Collection, Tabulation & Presentation', 'Revision of collection, tabulation and presentation of grouped data (heights, ages, weights, test/exam scores, class populations).', 311),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Range, Median & Mode (Grouped Data)', 'Calculation of range, median and mode of grouped data.', 312),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Statistical Graphs', 'Statistical graphs — drawing of bar chart, pie chart and histogram; cumulative frequency curve; reading and drawing inferences from graphs.', 313),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS1', 3, 'Mean Deviation, Variance & Standard Deviation', 'Mean deviation, variance and standard deviation of grouped data, applied to practical/real-life problems.', 314),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 1, 'Logarithms: Numbers Less Than One & Reciprocals', 'Revision of logarithm of numbers greater than one and logarithm of numbers less than one; reciprocals and accuracy of results using standard calculation.', 101),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 1, 'Approximations, Standard Form & Percentage Error', 'Approximations; calculations using standard form; significant figures; percentage error.', 102),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 1, 'Sequences & Series: Arithmetic Progression', 'Sequence and Series — concept of sequence and series; terms of Arithmetic Progressions (A.P.) and their sum; solving problems on A.P.', 103),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 1, 'Geometric Progression', 'Geometric Progressions — the nth term and sum of the first n terms; problem solving on G.P. and geometric mean.', 104),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 1, 'Quadratic Equations from Sum & Product of Roots', 'Construction of a quadratic equation from the sum and product of roots; word problems leading to quadratic equations.', 105),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 1, 'Simultaneous Equations: Elimination & Substitution', 'Simultaneous Equations — solving by elimination and substitution methods; word problems leading to simultaneous equations.', 106),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 1, 'Simultaneous Equations: Linear & Quadratic', 'Simultaneous Equations — solving equations involving one linear and one quadratic equation; using graphical methods to solve quadratic equations.', 107),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 1, 'Straight Line Graphs: Gradient', 'Straight Line Graphs — gradient of a straight line; gradient of a curve; drawing tangents to a curve.', 108),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 2, 'Gradient of a Straight Line & a Curve', 'Revision — Straight lines: gradient of a straight line, gradient of a curve, drawing of tangents to a curve.', 201),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 2, 'Inequalities in One and Two Variables', 'Inequalities — (a) revision of linear inequalities in one variable, (b) solutions of inequalities in two variables, (c) range of values of combined inequalities.', 202),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 2, 'Graphs of Linear Inequalities', 'Graphs of linear inequalities in two variables; maximum and minimum values of simultaneous linear inequalities.', 203),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 2, 'Linear Inequalities: Applications & Linear Programming', 'Application of linear inequalities to real life; introduction to linear programming.', 204),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 2, 'Algebraic Fractions', 'Algebraic Fractions — simplification of fractions; operations on algebraic fractions.', 205),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 2, 'Equations Involving Fractions', 'Equations involving fractions; undefined fractions (e.g. y is undefined when the denominator ax + c = 0).', 206),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 2, 'Fractions: Substitution & Simultaneous Equations', 'Fractions (continued) — substitution in fractions; simultaneous equations involving fractions.', 207),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 2, 'Logic: Compound Statements & Truth Tables', 'Logic — simple and compound statements; logical operations and truth tables; conditional statements and indirect proofs.', 208),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 2, 'Chord Properties of Circles', 'Chord properties of circles — perpendicular bisector of a chord; distance of equal chords from the centre of a circle; angles subtended by two equal chords.', 209),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 2, 'Circle Theorems: Angle Properties', 'Circle Theorems — angle properties of a circle; angle subtended by an arc at the centre is twice that subtended at the circumference; angles in the same segment; angles in a semicircle; opposite angles of a cyclic quadrilateral.', 210),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 3, 'Circle Theorems: Tangent Properties', 'Circle Theorems — tangent properties of a circle; angles in the alternate segment; two tangents from an external point.', 301),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 3, 'Sine Rule & Cosine Rule', 'Trigonometry — derivation of the sine rule and cosine rule and their applications.', 302),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 3, 'Bearing, Distances, Elevation & Depression', 'Bearing and Distances; Elevation and Depression.', 303),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 3, 'Statistics: Class Boundaries & Cumulative Frequency', 'Statistics — class boundaries, class marks, and cumulative frequencies of grouped data; histograms.', 304),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 3, 'Cumulative Frequency Curve (Ogive)', 'Statistics — cumulative frequency curve (Ogive); using the ogive to calculate the median, quartile, percentile and decile.', 305),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 3, 'Mean, Median & Mode of Grouped Data', 'Statistics — mean, median and mode of grouped data.', 306),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 3, 'Probability: Introduction', 'Probability — introduction; use of dice, coins and playing cards.', 307),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS2', 3, 'Probability: Addition & Multiplication Rules', 'Probability — addition and multiplication rules; mutually exclusive, independent and complementary events; experiments with or without replacement.', 308),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS3', 1, 'Revision: Indices and Logarithm', 'Revision: Indices and Logarithm.', 101),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS3', 1, 'Surds', 'Surds.', 102),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS3', 1, 'Surds in Relation to Trigonometry', 'Surds in relation to Trigonometry.', 103),
