  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS3', 2, 'Coordinate Geometry: Distance & Midpoint', 'Coordinate Geometry of straight lines — Cartesian coordinate graphs; distance between two points; midpoint of the line joining two points.', 202),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS3', 2, 'Coordinate Geometry: Gradient, Intercepts & Angle Between Lines', 'Coordinate Geometry of straight lines — gradient and intercepts of a line; angle between two intersecting straight lines and applications.', 203),
  ('b3f6b6a0-1c1a-4b8e-9c1e-000000000001', 'SS3', 2, 'Differentiation: First Principles & Standard Derivatives', 'Differentiation of algebraic functions — meaning of differentiation; differentiation from first principles; standard derivatives of basic functions.', 204),
